const {
	getState,
	itemType,
	polySources,
	commandFactory
} = options;
const itemTypeMetadata = ArasModules.metadata.itemType;
const isPolymorphic = itemTypeMetadata.isPolymorphic(itemType.id);
const getItemType = (item) => {
	if (isPolymorphic) {
		const itemTypeId = item.itemtype;
		const itemTypeName = itemTypeMetadata.getItemTypeName(itemTypeId);
		return polySources[itemTypeName];
	}

	return itemType;
};

const commandAlias = target['command_alias@keyed_name'];
const rows = window.grid._grid.rows;
const { grid } = getState();
const itemIdsToDelete = grid.selectedRows.filter((selectedId) => {
	const item = rows.get(selectedId);
	const itemType = getItemType(item);
	const deleteCommand = commandFactory(commandAlias, {
		...options,
		item,
		itemType,
		itemTypeName: itemType.name
	});
	const isDeleteCommandAllowed = deleteCommand.canExecute();

	return isDeleteCommandAllowed && !window.isFunctionDisabled(itemType.name, 'Delete');
});

if (itemIdsToDelete.length > 0) {
	return window.onDeleteCommand(itemIdsToDelete);
}
